source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json

# Check trace patterns in fail samples across conditions
for fname in ['full_trace_test', 'exception_only_test', 'ae_only_test', 'no_trace_test']:
    path = f'/root/autodl-tmp/trace-verdict-study-data/{fname}.jsonl'
    trace_patterns = {'no_trace': 0, 'has_exception': 0, 'has_trace_no_exception': 0, 'no_execution_trace_section': 0}
    pass_patterns = {'no_trace': 0, 'has_exception': 0, 'has_trace_no_exception': 0, 'no_execution_trace_section': 0}
    with open(path) as f:
        for line in f:
            s = json.loads(line)
            inp = s['input']
            is_pass = s['output'] == 'pass'
            patterns = pass_patterns if is_pass else trace_patterns

            trace_idx = inp.find('Execution trace:')
            if trace_idx < 0:
                patterns['no_execution_trace_section'] += 1
            else:
                trace = inp[trace_idx:]
                if '[No trace available]' in trace or '[No exception data]' in trace:
                    patterns['no_trace'] += 1
                elif 'Exception' in trace or 'Error' in trace or 'Traceback' in trace:
                    patterns['has_exception'] += 1
                else:
                    patterns['has_trace_no_exception'] += 1
    print(f'{fname}:')
    print(f'  PASS: {pass_patterns}')
    print(f'  FAIL: {trace_patterns}')
"

